    correctKey: 'D',
    explanation: '鉛蓄電池の電解液は希硫酸である。放電すると硫酸が消費されて水が生じるため電解液の比重が下がり、充電すると比重が戻る。この性質を利用して比重計で充電状態を判定できる。取扱いでは、希硫酸が皮膚や衣服を侵すこと、充電末期に水素ガスが発生して爆発の危険があることから、換気と火気厳禁が求められる。補水にはイオン交換水など精製水を用いる。\n\n【図解】鉛蓄電池の充放電と電解液\n　状態｜電解液の比重｜備考\n　満充電｜高い｜約1.28\n　放電後｜低い｜約1.10\n　⚠ 充電中は水素ガスが発生するため換気が必要\n\nアルカリ蓄電池は電解液に水酸化カリウム水溶液を用い、過酷な充放電に強く寿命が長いが、公称電圧は1.2Vと低い。用途に応じて鉛蓄電池と使い分ける。',
