    explanation: '太陽電池は光起電力効果によって直流を発生する。そのままでは屋内配線や電力系統で使えないため、パワーコンディショナ（パワコン）で直流を交流に変換し、電圧と周波数を系統に合わせて接続する。パワーコンディショナには、系統が停電したときに発電を止める単独運転防止機能が備えられており、作業者の感電を防いでいる。蓄電池の併設は任意である。\n\n【図解】住宅用太陽光発電の構成\n　機器｜入力｜出力\n　太陽電池モジュール｜太陽光｜直流\n　パワーコンディショナ｜直流｜交流\n　分電盤｜交流｜屋内負荷と系統\n　⚠ 停電時は単独運転防止機能により発電が停止する\n\n太陽電池は日射量と温度で出力が変わり、モジュール温度が高くなると出力電圧が下がって発電量が低下する。設置では通風と方位、傾斜角の確保が重要である。',
