    explanation: '漏電遮断器は零相変流器で回路の全電線を一括して取り囲み、行きの電流と帰りの電流の差を検出する。正常時は差が0だが、機器の絶縁不良などで電流の一部が大地へ流れると差が生じ、これを地絡電流として検出して回路を遮断する。人体が感電した場合にも同様に動作するため、感電による事故を防ぐ最も重要な保護装置である。\n\n【図解】漏電遮断器の検出原理\n　状態｜行きの電流｜帰りの電流\n　正常時｜10A｜10A\n　漏電時｜10A｜9.97A\n　⚠ 差の分が地絡電流として検出される\n\n漏電遮断器にはテストボタンがあり、定期的に押して動作を確認する必要がある。動作しない場合は速やかに取り替える。\n\n漏電遮断器は感電と漏電火災の両方を防ぐ要となる機器であり、住宅では分電盤の主幹に設けるのが一般的である。分岐回路ごとに設ければ、故障箇所の切り分けも容易になる。',
