    correctKey: 'A',
    explanation: '600V二種ビニル絶縁電線は記号HIVで表され、耐熱性を高めたビニルを絶縁体に用いた電線で、最高許容温度は75℃である。一般のIVが60℃であるのに対して高温に耐えるため、消防設備の配線や高温になる場所、太い電線を許容電流いっぱいで使う箇所などに用いられる。外観はIVと似ているので、材料の判別問題では表示や色で区別する。\n\n【図解】絶縁電線の最高許容温度\n　種類｜最高許容温度\n　IV（600Vビニル絶縁電線）｜60℃\n　HIV（600V二種ビニル絶縁電線）｜75℃\n　CVケーブル（架橋ポリエチレン）｜90℃\n　⚠ 許容温度が高いほど同じ太さでも許容電流が大きい\n\n許容温度の違いは許容電流に直結する。周囲温度が高い場所や電線を多数まとめる場合は、電流減少係数を掛けて許容電流を補正する必要がある。',
