    explanation: 'ろう付けによる接続では、まず電線どうしを確実に絡げて機械的な強度を確保し、そのうえで十分に加熱してろうを流し込み、最後に絶縁電線と同等以上の絶縁処理を施す。ろう付けはあくまで電気的な接続を確実にするためのもので、はんだだけで強度を保たせてはならない。またフラックスが残ると腐食して接触不良を招くので、作業後に確実に除去する。\n\n【図解】ろう付けの手順\n　順序｜作業\n　1｜被覆をむき心線を清浄にする\n　2｜心線どうしを十分に絡げる\n　3｜加熱してろうを流し込む\n　4｜フラックスを除去し絶縁処理する\n　⚠ はんだだけで強度を持たせない\n\n現在の屋内配線ではリングスリーブや差込形コネクタが主流であり、ろう付けは特殊な箇所に限られるが、接続の原則を理解するうえで押さえておくべき知識である。',
    difficulty: 'basic',
