    correctKey: 'D',
    explanation: 'リーマは、金属管を金切りのこで切断したあとに管の内側に残るばりを削り取る工具である。ばりが残ったまま電線を引き入れると絶縁被覆が傷つき、漏電や短絡の原因になるため、切断後は必ずばり取りを行う。リーマはクリックボールに取り付けて回して使うのが一般的である。外面のばりや切り口の仕上げにはやすりを併用する。\n\n【図解】金属管の切断から接続までの手順\n　順序｜作業｜工具\n　1｜管を切断する｜金切りのこ\n　2｜内面のばりを取る｜リーマとクリックボール\n　3｜管端にねじを切る｜ねじ切り器\n　4｜管を接続する｜カップリング\n　⚠ ばり取りを省くと電線の被覆を傷める\n\nボックスに引き込む管端には絶縁ブッシングを取り付け、電線の被覆をさらに保護する。これも施工上の基本事項である。',
    difficulty: 'basic',
