    correctKey: 'A',
    explanation: '電圧600V以下で使用する電気機器（配線器具を除く）または蓄電池の端子に電線をねじ止めする工事は軽微な工事に該当する。機器側の端子への接続であり、屋内配線そのものを構成する作業ではないからである。これに対し、がいしへの電線の取付け、造営材への電線の直接取付け、金属製ボックスの取付けなどは、いずれも電気工事士でなければ従事できない作業である。\n\n【図解】判断の分かれ目\n　作業の対象｜資格の要否\n　機器の端子へのねじ止め｜不要（軽微な工事）\n　屋内配線の電線相互の接続｜必要\n　造営材への電線や器具の取付け｜必要\n　⚠ 配線側か機器側かで判断する\n\nこの区別は毎年のように出題される。配線そのものを作る作業は資格が必要、機器につなぐだけの作業や付随的な作業は軽微な工事、という原則で判断するとよい。',
    difficulty: 'basic',
