    explanation: '一般用電気工作物の電気工事を行う電気工事業者は、営業所ごとに絶縁抵抗計、接地抵抗計、および抵抗と交流電圧を測定できる回路計を備えなければならない。これらは竣工検査で必ず使用する測定器であり、工事の品質を確認するために不可欠だからである。自家用電気工作物の工事も行う場合には、低圧検電器、高圧検電器、継電器試験装置、絶縁耐力試験装置も必要となる。\n\n【図解】備え付ける器具と用途\n　器具｜測定する項目\n　絶縁抵抗計｜電路と大地間などの絶縁抵抗\n　接地抵抗計｜接地極の接地抵抗\n　回路計｜抵抗と交流電圧、導通の確認\n　⚠ 自家用も扱う場合は器具が追加される\n\n備え付けた器具は必要に応じて校正し、正しい測定ができる状態を保つ必要がある。測定器の管理も業者としての重要な責務である。',
