    explanation: '導通試験は、回路計の抵抗レンジやブザー機能を用いて、電線がつながっているかどうかを確認する試験である。配線の誤り、断線、器具の接続忘れ、極性の誤りなどを発見できる。停電状態で行い、点滅器の入切に応じて導通の有無が変わることを確認すれば、スイッチが正しく非接地側に入っているかも判定できる。通電前に行うのが原則である。\n\n【図解】測定器と検査項目\n　測定器｜検査項目\n　回路計｜導通、抵抗、交流電圧\n　絶縁抵抗計｜絶縁抵抗\n　接地抵抗計｜接地抵抗\n　クランプメータ｜負荷電流、漏えい電流\n　⚠ 測定器ごとに測れる項目が決まっている\n\n回路計は交流電圧の測定にも用いるが、電圧を測るときは必ずレンジを電圧に切り替える。抵抗レンジのまま電圧を測ると測定器を損傷する。',
