    correctKey: 'A',
    explanation: '露出配線は点線で示す。造営材の表面に沿ってケーブルや電線管を取り付ける配線方法で、外から配線が見える状態である。既設の建物への増設工事や、工場、倉庫などで多く用いられる。露出配線では、支持点間の距離や造営材への固定方法、器具との取合いなどが目に見えるため、施工の丁寧さがそのまま仕上がりの印象を左右する。\n\n【図解】配線の線種のまとめ\n　線種｜配線の種別\n　実線｜天井隠ぺい配線\n　破線｜床隠ぺい配線\n　点線｜露出配線\n　一点鎖線｜地中埋設配線\n　⚠ 4種類をセットで覚える\n\n露出配線ではケーブル工事のほか金属管工事、合成樹脂管工事、金属線ぴ工事などが用いられる。施設場所の条件により選べる工事が変わる点にも注意する。',
    difficulty: 'basic',
