    correctKey: 'D',
    explanation: '添字Hは位置表示灯内蔵スイッチを表す。スイッチが切のときに内蔵ランプが点灯し、暗い場所でスイッチの位置を示す。回路としては異時点滅と同じで、パイロットランプがスイッチと並列に接続された状態になる。これに対して添字Lの確認表示灯内蔵スイッチは、スイッチが入のときに点灯し、同時点滅の結線となる。\n\n【図解】表示灯付きスイッチの添字\n　添字｜名称｜点灯するとき\n　H｜位置表示灯内蔵｜スイッチが切のとき\n　L｜確認表示灯内蔵｜スイッチが入のとき\n　⚠ HとLで動作も結線も逆になる\n\n配線図でHやLの添字を見たら、複線図を書くときにパイロットランプの接続先が変わることを意識する。電線の本数やスリーブの数に影響する。',
    difficulty: 'standard',
