    correctKey: 'C',
    explanation: '添字Lは確認表示灯内蔵スイッチを表す。スイッチが入のときに表示灯が点灯し、離れた場所にある負荷が動作していることを手元で確認できる。結線はパイロットランプを負荷と並列に接続する同時点滅となる。換気扇や屋外灯など、動作状態が見えない負荷の制御に用いられる。添字LとLKは意味が異なるので混同しないよう注意する。\n\n【図解】紛らわしい添字\n　添字｜意味｜対象\n　L｜確認表示灯内蔵｜点滅器\n　LK｜抜け止め形｜コンセント\n　H｜位置表示灯内蔵｜点滅器\n　⚠ 添字が付く器具の種類も合わせて確認する\n\n配線図では点滅器とコンセントが隣り合って描かれることが多く、どちらの記号に添字が付いているかを見誤らないよう丁寧に読む必要がある。',
